head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dataDragSelect]<br/>마우스 Drag 를 사용한 다중 Cell 선택(직사각형) 기능을 활성화합니다.",
    "validation" : [
        "blockSelect=true 인 Cell 은 Drag 가 시작되거나 선택 처리되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_src !== 'undefined') { $p.data.remove("dlt_src"); }

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - dataDragSelect=true, useShiftKey=true 고정. col2 컬럼은 blockSelect="true" 로 선택 차단.
    $c.gcm.createLabel('label="dataDragSelect=true + useShiftKey=true 고정. col2 컬럼은 blockSelect=true 로 설정됨. col1~col4 를 가로질러 Drag 하여 직사각형 선택 후 [선택 Cell 확인] → blockSelect 인 col2(컬럼 인덱스 1) Cell 은 선택에서 제외됩니다. col2 에서 Drag 를 시작하면 선택이 시작되지 않습니다."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === DataList(dlt_src) : 4 Column ===
    let strSrc = '';
    strSrc += '<w2:dataList ' + strNameSpace + ' id="dlt_src" baseNode="list" repeatNode="map">';
    strSrc += '<w2:columnInfo>';
    strSrc += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strSrc += '</w2:columnInfo>';
    strSrc += '<w2:data use="true"></w2:data>';
    strSrc += '</w2:dataList>';
    $p.data.create(strSrc);

    let srcData = [
        { "col1": "행1", "col2": "100", "col3": "Aa", "col4": "10" },
        { "col1": "행2", "col2": "200", "col3": "Bb", "col4": "20" },
        { "col1": "행3", "col2": "300", "col3": "Cc", "col4": "30" },
        { "col1": "행4", "col2": "400", "col3": "Dd", "col4": "40" }
    ];
    dlt_src.setJSON(srcData, false);

    let grp_comp = $c.gcm.getTestGroup();

    // === target1 : dataDragSelect=true + useShiftKey=true 고정. col2 에 blockSelect="true" ===
    let srcCList = $c.gcm.createCList({ dataList: "data:dlt_src", dataDragSelect: true, useShiftKey: true });

    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' ' + srcCList + ' id="" style="width:440px;height:300px;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="target1 (col2 = blockSelect)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2(block)"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2" blockSelect="true"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);
};



// 선택 Cell 확인 : Drag 로 선택된 모든 Cell 의 row/col 인덱스를 출력
//  - blockSelect=true 인 col2(컬럼 인덱스 1)는 선택 배열에 포함되지 않아야 함
scwin.btn_checkSelected_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let rtn = target1.getAllFocusedIndex();
    if (rtn && rtn.length > 0) {
        b.setReturnValue("선택된 Cell 수 : " + rtn.length);
        let hasBlocked = false;
        for (let i = 0; i < rtn.length; i++) {
            b.setReturnValue("  [" + i + "] row=" + rtn[i].row + ", col=" + rtn[i].col);
            if (rtn[i].col === 1) { hasBlocked = true; }
        }
        b.setReturnValue("blockSelect 컬럼(col2, 인덱스 1) 포함 여부 : " + hasBlocked);
    } else {
        b.setReturnValue("선택된 Cell 없음 (빈 배열)");
    }
};
